<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_role(['admin','organizer']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$event=(int)($_POST['event_id']??0);$app=(int)($_POST['application_id']??0);$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');if($event && $app && $title){$s=$pdo->prepare("INSERT INTO tasks(event_id,application_id,title,description,assigned_by) SELECT ?,?, ?,?,? WHERE EXISTS(SELECT 1 FROM volunteer_applications WHERE id=? AND event_id=? AND status='approved')");$s->execute([$event,$app,$title,$desc,current_user()['id'],$app,$event]);flash('Task assigned.');}else flash('Please complete all required fields.','error');redirect('tasks.php');}
$pageTitle='Tasks';$events=$pdo->query("SELECT id,title FROM events ORDER BY event_date DESC")->fetchAll();$approved=$pdo->query("SELECT va.id,va.event_id,u.name,e.title AS event_title FROM volunteer_applications va JOIN users u ON u.id=va.student_id JOIN events e ON e.id=va.event_id WHERE va.status='approved' ORDER BY e.event_date DESC")->fetchAll();$tasks=$pdo->query("SELECT t.title,t.description,e.title AS event_title,u.name FROM tasks t JOIN events e ON e.id=t.event_id JOIN volunteer_applications va ON va.id=t.application_id JOIN users u ON u.id=va.student_id ORDER BY t.created_at DESC")->fetchAll();require __DIR__.'/includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">ORGANIZER WORKSPACE</span><h1>Task management</h1><p>Assign clear responsibilities to approved volunteers.</p></section>
<div class="split-layout"><form class="form-card" method="post"><h2>Assign a task</h2><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Event<select name="event_id" required><option value="">Choose event</option><?php foreach($events as $ev):?><option value="<?=$ev['id']?>"><?=e($ev['title'])?></option><?php endforeach;?></select></label><label>Approved volunteer<select name="application_id" required><option value="">Choose volunteer</option><?php foreach($approved as $a):?><option value="<?=$a['id']?>"><?=e($a['name'].' — '.$a['event_title'])?></option><?php endforeach;?></select></label><label>Task title<input name="title" required></label><label>Description<textarea name="description" rows="3"></textarea></label><button class="btn btn-primary">Assign task</button></form><div><h2>Assigned tasks</h2><div class="stack-list"><?php foreach($tasks as $t):?><div class="list-card"><div><strong><?=e($t['title'])?></strong><small><?=e($t['event_title'])?> · <?=e($t['name'])?></small><p><?=e($t['description'])?></p></div></div><?php endforeach;?><?php if(!$tasks):?><div class="empty-state">No tasks assigned yet.</div><?php endif;?></div></div></div>
<?php require __DIR__.'/includes/footer.php';?>
